import"./hoisted.C5jVAxwv.js";const i=n=>"GHS "+n.toLocaleString("en-GH",{minimumFractionDigits:2,maximumFractionDigits:2});document.getElementById("go").addEventListener("click",()=>{const n=parseFloat(document.getElementById("rent").value),t=parseInt(document.getElementById("months").value,10),e=parseInt(document.getElementById("type").value,10);if(!n||!t||n<=0||t<=0)return;document.getElementById("total").textContent=i(n*t),document.getElementById("period").textContent=t+(t===1?" month":" months")+(t>=12?" ("+(t/12).toFixed(t%12===0?0:1)+" year"+(t>12?"s":"")+")":"");const o=document.getElementById("verdict");t<=e?o.textContent="This demand is within the statutory ceiling of "+e+" month"+(e>1?"s":"")+" for this tenancy type.":o.textContent="This demand exceeds the statutory ceiling of "+e+" month"+(e>1?"s":"")+" for this tenancy type by "+(t-e)+" month"+(t-e>1?"s":"")+" — equivalent to "+i(n*(t-e))+" beyond the Act 220 position.",document.getElementById("result").hidden=!1});
